use vstd::prelude::*;

verus! {

type Matrix<T> = Vec<Vec<T>>;

/// Broadcasts a 1-D vector `a` into a 2-D matrix of shape `shape`,
/// either by treating `a` as a column (when `a.len() == shape[0]`)
/// or as a row    (when `a.len() == shape[1]`).
fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> (matrix: Matrix<i8>)
    requires
        // shape must have exactly two dimensions
        shape.len() == 2,
        // either we are broadcasting a column or a row
        a.len() == shape[0] as usize
         || a.len() == shape[1] as usize,
    ensures
        // the result has exactly shape[0] rows
        matrix.len() == shape[0] as usize,
        // each row has exactly shape[1] columns and the right broadcasted entries
        forall |i: usize, j: usize|
            i < shape[0] as usize && j < shape[1] as usize ==>
            matrix[i][j] ==
                if a.len() == shape[0] as usize {
                    // column-broadcast: each row i is filled with a[i]
                    a[i]
                } else {
                    // row-broadcast: each column j in every row is a[j]
                    a[j]
                },
{
    // runtime check on the shape
    assert!(shape.len() == 2, "shape must have exactly two dimensions");
    let rows = shape[0] as usize;
    let cols = shape[1] as usize;
    let len = a.len();

    if len == rows {
        // column vector case
        let mut matrix = Vec::with_capacity(rows);
        let mut i = 0;
        while i < rows
            invariant
                // we still know shape is length 2
                shape.len() == 2,
                // in this branch we have a.len()==rows
                a.len() == rows,
                // we have built exactly i rows so far
                matrix.len() == i,
                // each of those i rows is a copy of [ a[0], a[0], … ],
                // … up to [ a[i−1], a[i−1], … ]
                forall |i0: usize, j0: usize|
                    i0 < matrix.len() && j0 < cols ==>
                    matrix[i0][j0] == a[i0],
            decreases rows - i,
        {
            // build row i by repeating a[i] across all cols
            matrix.push(vec![a[i]; cols]);
            i += 1;
        }
        matrix
    } else if len == cols {
        // row vector case
        let mut matrix = Vec::with_capacity(rows);
        let mut i = 0;
        while i < rows
            invariant
                shape.len() == 2,
                a.len() == cols,
                matrix.len() == i,
                // each built row is exactly a.clone()
                forall |i0: usize, j0: usize|
                    i0 < matrix.len() && j0 < cols ==>
                    matrix[i0][j0] == a[j0],
            decreases rows - i,
        {
            matrix.push(a.clone());
            i += 1;
        }
        matrix
    } else {
        // according to our precondition this cannot happen
        panic!("Length of the array must equal either number of rows or number of columns");
    }
}

} // end verus!

fn main() {
    // example runs
    let v = vec![1_i8, 2, 3];
    let shape_col = vec![3_u8, 4];
    let mcol = broadcast(v.clone(), shape_col);
    assert!(mcol.len() == 3);
    assert!(mcol[1][2] == 2);

    let shape_row = vec![5_u8, 3];
    let mrow = broadcast(v, shape_row);
    assert!(mrow.len() == 5);
    assert!(mrow[4][0] == 1);
}